const r = await tools.exec_command({"cmd":"../.venv-test/bin/python - <<'PY'
import json, random, re
from pathlib import Path
root=Path('runs/table-diagnostic-e1-s4008')
episodes=[json.loads(x) for x in (root/'episodes_development_table.jsonl').read_text().splitlines()]
rng=random.Random(17)
remaining=list(range(len(episodes)))
strata=[]
def take(name,pred,n):
 global remaining
 eligible=[i for i in remaining if pred(episodes[i])]
 chosen=sorted(rng.sample(eligible,min(n,len(eligible))))
 remaining=[i for i in remaining if i not in chosen]
 strata.append((name,len(eligible),chosen))
take('budget',lambda e:e['stop_reason'] in {'max_turns','hit_generation_cap'},6)
take('voluntary',lambda e:e['stop_reason']=='no_tool_call',6)
take('invalid_or_repeated',lambda e:e['n_invalid_actions']>0 or e['n_repeated_actions']>0,6)
correct=[i for i in remaining if episodes[i]['correct']]
lengths=sorted(episodes[i]['n_tokens'] for i in correct); cutoff=lengths[max(0,(len(lengths)-1)//4)] if lengths else 0
take('efficient_correct',lambda e:e['correct'] and e['n_tokens']<=cutoff,6)
for name,total,chosen in strata:
 print(name,'eligible',total,'selected',chosen)
 for i in chosen:
  e=episodes[i]; cells=re.findall(r"gridcell '([^']*)'",e['initial_observation']); table=dict(zip(cells[::2],cells[1::2],strict=True)); fields=re.findall(r"StaticText '([^']*):'\n\s*\[(\d+)\] textbox",e['initial_observation']); expected={label:table[label] for label,_ in fields}
  finals=[]; errors=[]
  for t in e['turns']:
   for call,res in zip(t['tool_calls'],t['tool_results']):
    content=res['content'];
    if content.startswith('Action error'): errors.append(call['name']+':'+str(call['arguments'].get('bid')))
    if call['name']=='click' and not content.startswith('Action error'): finals.append(content[-450:].replace('\n',' '))
  print(json.dumps({'index':i,'seed':e['seed'],'tokens':e['n_tokens'],'steps':e['n_steps'],'stop':e['stop_reason'],'actions':e['tool_calls'],'invalid':e['n_invalid_actions'],'repeated':e['n_repeated_actions'],'expected':expected,'terminal_tail':finals[-1] if finals else None,'native_errors':errors},ensure_ascii=True))
PY
