"""Run one separate review job per completed diagnostic phase; never resume the app writer."""

import json
import subprocess
import sys
from pathlib import Path

ROOT = Path.home() / "Documents/Projects/Uni/Master_Thesis/master-thesis-code"
CLAIMS = Path("/private/tmp/table-diagnostic-review-claims")
ROLLOUT = (
    Path.home()
    / ".codex/sessions/2026/09/11/rollout-2026-09-11T19-38-59-01a0918d-1d59-72f0-9db1-d823c5043ee6.jsonl"
)


def thread_idle():
    with ROLLOUT.open("rb") as handle:
        handle.seek(max(0, ROLLOUT.stat().st_size - 2_000_000))
        lines = handle.read().splitlines()
    for line in reversed(lines):
        try:
            row = json.loads(line)
        except (ValueError, UnicodeError):
            continue
        kind = row.get("payload", {}).get("type")
        if row.get("type") == "event_msg" and kind in {
            "task_started",
            "task_complete",
            "turn_aborted",
        }:
            return kind == "task_complete"
    return False


def review(run, prompt, read_only=False):
    CLAIMS.mkdir(exist_ok=True)
    claim = CLAIMS / run
    try:
        claim.mkdir()
    except FileExistsError:
        print("Review already claimed:", run, flush=True)
        return
    result_path = claim / "result.md"
    command = [
        "/bin/zsh",
        "-eu",
        "-c",
        'source "$HOME/.codex/models.env"; '
        "exec /opt/homebrew/bin/codex exec "
        + ("--sandbox read-only " if read_only else "--approve-for-me ")
        + '-m "$MODEL_REVIEWER" -c "model_reasoning_effort=$EFFORT_REVIEWER" '
        + '--output-last-message "$1" -',
        "review",
        str(result_path),
    ]
    (claim / "status.json").write_text(json.dumps({"status": "started"}) + "\n")
    with Path(prompt).open() as text:
        result = subprocess.run(command, cwd=ROOT, stdin=text)
    (claim / "status.json").write_text(
        json.dumps({"status": "finished", "returncode": result.returncode}) + "\n"
    )
    sys.exit(result.returncode)


def main():
    if "--verify-handoff" in sys.argv:
        review(
            "launcher-review",
            "/private/tmp/table-diagnostic-launcher-review.md",
            read_only=True,
        )
        return
    if not thread_idle():
        print("Research thread active; deferring review.", flush=True)
        return
    result = subprocess.run(
        [
            "/usr/bin/ssh",
            "-o",
            "BatchMode=yes",
            "-o",
            "ConnectTimeout=15",
            "gpu-l4",
            "cat /workspace/master-thesis-code/pipeline/runs/table-diagnostic-s4008-ops/state.json",
        ],
        text=True,
        capture_output=True,
        check=True,
        timeout=30,
    )
    state = json.loads(result.stdout)
    print(json.dumps(state), flush=True)
    assert state["run"] in {"table-diagnostic-e0-s4008", "table-diagnostic-e1-s4008"}
    if state["phase"] not in {
        "done, unharvested; review pending",
        "stopped; review required",
    }:
        return
    if "--check-only" not in sys.argv:
        review(state["run"], "/private/tmp/table-diagnostic-review-prompt.md")


if __name__ == "__main__":
    main()
